    static void check(boolean b) { assertions++; if (!b) throw new AssertionError("assertion " + assertions); }
    static Map<String, Object> copyMap(Object o) {
        if (!(o instanceof Map<?, ?> m)) throw new AssertionError();
        Map<String, Object> result = new java.util.LinkedHashMap<>();
        for (Map.Entry<?, ?> e : m.entrySet()) result.put((String)e.getKey(), e.getValue());
        return result;
    }
    static Map<String, Object> mutateItem(Consumer<Map<String, Object>> edit) {
        Map<String, Object> root = ProcurementNlPrecheck.fixtureData(RAW);
        List<?> old = (List<?>)root.get("items");
        Map<String, Object> item = copyMap(old.get(0));
        edit.accept(item);
        root.put("items", List.of(item));
        return root;
    }
    static ProcurementNlPrecheck.Report run(String label, String raw, ProcurementNlPrecheck.Employee employee,
            ProcurementNlPrecheck.Extractor extractor, ProcurementNlPrecheck.Confirmation confirmation) {
        return runWithTimeout(label, raw, employee, extractor, confirmation, SUCCESS_TIMEOUT_MILLIS);
    }
    static ProcurementNlPrecheck.Report runWithTimeout(String label, String raw,
            ProcurementNlPrecheck.Employee employee, ProcurementNlPrecheck.Extractor extractor,
            ProcurementNlPrecheck.Confirmation confirmation, long timeoutMillis) {
        // Success cases tolerate cold startup; only explicit timeout cases use the short deadline.
        try (ProcurementNlPrecheck.Engine engine = new ProcurementNlPrecheck.Engine(extractor, timeoutMillis)) {
            ProcurementNlPrecheck.Report report = engine.check(raw, employee, confirmation);
            record(label, report);
            return report;
        }
    }
    static void record(String label, ProcurementNlPrecheck.Report report) {
        reports++;
        check(report.actions().size() == 4);
        check(report.actions().stream().map(ProcurementNlPrecheck.Decision::action).distinct().count() == 4);
        check(report.actions().get(3).status() != ProcurementNlPrecheck.Status.ALLOWED);
        check(report.explanation().contains("未执行任何内部动作"));
        Object decoded = ProcurementNlPrecheck.Json.parse(report.json());
        check(Boolean.TRUE.equals(((Map<?, ?>)decoded).get("report_only")));
        System.out.println(ProcurementNlPrecheck.Json.write(ProcurementNlPrecheck.obj("case", label, "report", decoded)));
    }
    static ProcurementNlPrecheck.Report candidate(String label, Map<String, Object> input) {
        return run(label, RAW, ProcurementNlPrecheck.demoEmployee(), s -> ProcurementNlPrecheck.Json.write(input), null);
    }
    static void invalid(String label, Map<String, Object> input) {
        ProcurementNlPrecheck.Report r = candidate(label, input);
        check(r.extractionState().equals("CANDIDATE_INVALID"));
        check(r.actions().stream().allMatch(d -> d.status() == ProcurementNlPrecheck.Status.NEEDS_INFO));
    }
    public static void main(String[] args) throws Exception {
