        check(confirmed.actions().get(1).status() == ProcurementNlPrecheck.Status.ALLOWED);
        check(confirmed.actions().get(2).status() == ProcurementNlPrecheck.Status.ALLOWED);
        check(confirmed.actions().get(3).status() == ProcurementNlPrecheck.Status.NEEDS_APPROVAL);
        check(run("determinism", RAW, employee, fixtures, confirmation).json().equals(confirmed.json()));
        ProcurementNlPrecheck.Employee other = new ProcurementNlPrecheck.Employee("other", true, Set.of("catalog", "request"), BigDecimal.TEN);
